# ---------------------------------------------------------------- readers
def sf_members(path):
    """SoulsFormats read: -> (ordered [(name, bytes)], version string)."""
    bnd = oreg.decrypt(path)
    mem = [(os.path.basename(str(f.Name).replace("\\", "/")), C.raw(f)) for f in bnd.Files]
    return mem, str(bnd.Version)


class Table:
    """one .param: descriptors, PARAMDEF layout, raw rows. Row data is addressed by its descriptor offset."""

    def __init__(self, name, blob):
        self.name, self.blob = name, blob
        P = oparam.Param(blob)
        pt = P.type_region.split(b"\0", 1)[0].decode("ascii", "replace")
        if pt not in pio.defs():
            pt = str(pio.read_param(blob)[0].ParamType)
        self.ptype, self.L, self.stride = pt, F.layout(pt), P.stride
        if self.L["__size__"] != self.stride:
            raise SystemExit("%s layout %d != stride %d" % (name, self.L["__size__"], self.stride))
        n = struct.unpack_from("<H", blob, 0x0A)[0]
        self.desc = [struct.unpack_from("<iIqq", blob, 0x40 + 24 * i) for i in range(n)]
        self.off = {}
        for rid, _p, doff, _n in self.desc:
            self.off.setdefault(rid, []).append(doff)
        shared = collections.Counter(d[2] for d in self.desc)
        self.unsafe = {d[0] for d in self.desc if shared[d[2]] > 1 or len(self.off[d[0]]) > 1}

    def ids(self):
        return list(self.off)

    def has(self, rid):
        return rid in self.off

    def row(self, rid):
        o = self.off[rid][0]
        return self.blob[o:o + self.stride]

    def get(self, rid, field):
        return F.get(self.L[field], self.row(rid))

    def all_rows(self):
        """every descriptor in file order (duplicate ids included): [(id, row bytes)]"""
        return [(d[0], self.blob[d[2]:d[2] + self.stride]) for d in self.desc]

    def patched(self, ids, field, value):
        """copy of the blob with `field` = value on each id, written in place (same length)."""
        buf = bytearray(self.blob)
        fl = self.L[field]
        for rid in ids:
            if rid not in self.off:
                raise SystemExit("ABORTING: %s row %d absent at patch time" % (self.name, rid))
            if rid in self.unsafe:
                raise SystemExit("ABORTING: %s row %d is duplicated or shares its data" % (self.name, rid))
            o = self.off[rid][0]
            row = bytearray(buf[o:o + self.stride])
            F.put(fl, row, value)
            buf[o:o + self.stride] = row
        return bytes(buf)


def calibrate(tbl, fields, ids=None):
    """LAW 2: our layout must read exactly what SoulsFormats reads, for every listed field on every row."""
    p, ok = pio.read_param(tbl.blob)
    if not ok:
        raise SystemExit("SoulsFormats could not apply the PARAMDEF to %s" % tbl.name)
    sf = list(p.Rows)                        # SoulsFormats keeps descriptor order, duplicates included
    if [int(r.ID) for r in sf] != [d[0] for d in tbl.desc]:
        raise SystemExit("%s: SoulsFormats row order differs from the descriptors" % tbl.name)
    want = None if ids is None else set(ids)
    bad, n = [], 0
    for (rid, data), r in zip(tbl.all_rows(), sf):
        if want is not None and rid not in want:
            continue
        for f in fields:
            a = F.get(tbl.L[f], data)
            b = F._sf_value(r[String(f)].Value)
            ok = (a == b) or (isinstance(b, bool) and int(a) == int(b)) or \
                 (isinstance(a, float) and abs(a - float(b)) <= 1e-6 * max(1.0, abs(float(b))))
            n += 1
            if not ok:
                bad.append((rid, f, a, b))
    if bad:
        raise SystemExit("LAYOUT CALIBRATION FAILED on %s: %s" % (tbl.name, bad[:5]))
    return n


