def fmg_names(msg):
    if not os.path.isfile(msg):
        raise SystemExit("weapon-name msgbnd missing: %s (pass --msg)" % msg)
    cwd = os.getcwd()
    os.chdir(os.path.dirname(C.OO))          # SoulsFormats finds oo2core (KRAK) through the cwd
    try:
        mem = C.members(msg)
    finally:
        os.chdir(cwd)
    fbt = clr.GetClrType(SoulsFormats.FMG).BaseType
    rd = [m for m in fbt.GetMethods() if m.Name == "Read" and m.GetParameters().Length == 1
          and m.GetParameters()[0].ParameterType.Name.startswith("Memory")][0]
    names = {}
    for f in ("WeaponName.fmg", "WeaponName_dlc01.fmg", "WeaponName_dlc02.fmg"):   # later wins
        if f not in mem:
            raise SystemExit("weapon-name FMG missing: %s in %s" % (f, msg))
        fm = rd.Invoke(None, Array[Object]([Memory[Byte](Array[Byte](mem[f]))]))
        for e in fm.Entries:
            names[int(e.ID)] = "%null%" if e.Text is None else str(e.Text)   # WitchyBND's null marker
    return {i: s.strip() for i, s in names.items()
            if s.strip() and s.strip() not in ("%null%",) and not s.strip().startswith("[ERROR]")}


