def _ext_line():
    pref = (98700000, 98100000, 98400000, 177770200, 177770000, 97400000)
    # v6.4: examples skip martial arts / perfume bottles, which get their own words below (v6.3 listed four
    # perfume bottles AND "the perfume bottles").
    ex = [EXT_INFO[i]["name"] for i in pref if i in EXT_INFO][:4] or \
         [EXT_INFO[i]["name"] for i in EXT if EXT_INFO[i]["name"] and EXT_INFO[i]["wepType"] not in ("88", "89")][:4]
    if any(EXT_INFO[i]["wepType"] == "88" for i in EXT):
        ex.append("the martial arts")
    if any(EXT_INFO[i]["wepType"] == "89" for i in EXT):
        ex.append("the perfume bottles")
    s = ("Since V6.2 this also covers the %d Shadow of the Erdtree, Clever and McKenyu "
         "weapons that earlier add-ons skipped (%s and more)." % (len(EXT), ", ".join(ex)))
    return "\n".join(textwrap.wrap(s, 76))


