manifest = dict(input=REG_IN, input_md5=IN_MD5, version_stamp=IN_STAMP, ver=VER, enh=A.enh, date=DATE,
                frame=_STOCK_FRAME.hex(" "), msg=MSG, msg_md5=md5(MSG) if os.path.isfile(MSG) else None,
                selection=dict(conv=conv_path, conv_md5=md5(conv_path), merge=merge_path, merge_md5=md5(merge_path),
                               drop_bad=sorted(DROP_BAD), vyke_fix=dict(id=VYKE, editions=VYKE_IN)),
                never_infinite={str(k): v for k, v in NEVER.items()}, never_present=NEVER_PRESENT,
                flips_legacy=len(LEGACY), flips_added=EXT_INFO, already_infinite=already, drift=drift,
                merge_dur_drift=merge_dur_drift, zips={})
for tag, label, desc in VARIANTS:
    reg, nenh = built[tag]
