    nmerge = len([c for c in merge if c["id"] in set(ids)])
    fmt = dict(ver=VER, label=label, desc=desc, n=len(ids), m=nmerge, enh=nenh, date=DATE,
               extline=_ext_line() if EXT else "")
    txt = HEAD.format(**fmt) + MERGE_KEPT.format(**fmt) + (VYKE_LINE if VYKE in ids else "") + \
        (ENH_REAL if EXT else ENH_LEGACY).format(**fmt) + TAIL.format(**fmt)
    body = [txt]
    for rid in ids:
        body.append(" SpEffect %-10d %s\n" % (rid, labels.get(str(rid), "")))
    data = open(reg, "rb").read()
    out = os.path.join(OUT, "Convergence X Clever X Mckenyu %s - Infinite Durations ADD-ON "
                            "(REQUIRES %s) - %s.zip" % (VER, VER, label))
    if os.path.exists(out):
        raise SystemExit("refusing to overwrite %s" % out)
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as z:
        z.writestr("CHANGELOG.txt", "".join(body))
        z.writestr("mod/regulation.bin", data)
    rmd5 = hashlib.md5(data).hexdigest()
    manifest["zips"][tag] = dict(file=os.path.basename(out), regulation_md5=rmd5, effects=len(ids),
                                 merge_effects=nmerge, isEnhance_flips=nenh, vyke=VYKE in ids)
    print("  %-26s %-5d effects (%d merge)  %s  %.1f MB"
          % (label, len(ids), nmerge, rmd5[:12], os.path.getsize(out) / 1048576.0))

